{"command":"python - <<'PY'
import pandas as pd, numpy as np
pce=pd.read_excel('/root/ERP-2025-table10.xls', header=None)
pfi=pd.read_excel('/root/ERP-2025-table12.xls', header=None)

def get_annual(df):
    out=[]
    for _,r in df.iterrows():
        y=r[0]
        if isinstance(y,str) and y.strip().endswith('.') and y.strip()[:4].isdigit():
            year=int(y.strip()[:4])
            if 1973<=year<=2023:
                out.append((year,r[1]))
    return pd.Series(dict(out)).sort_index()
print(get_annual(pce).head(), get_annual(pce).tail(), len(get_annual(pce)))
print(get_annual(pfi).head(), get_annual(pfi).tail(), len(get_annual(pfi)))
print('2024 rows pce', [r[0] for _,r in pce.iterrows() if isinstance(r[0],str) and '2024' in r[0]])
print('2024 rows pfi', [r[0] for _,r in pfi.iterrows() if isinstance(r[0],str) and '2024' in r[0]])
